add(tab='3825P / 7268P / 8568P - Cortech Barracuda Box', short='3825P / 7268P / 8568P: Cortech Barracuda Inmate Property Storage Box',
 handle='cortech-barracuda-box-inmate-property-storage', src=CP+'property-storage/barracuda-box/', specs=[SPEC_BB],
 h1='Cortech Barracuda Inmate Property Storage Box – 3825P / 7268P / 8568P',
 cur_h1='Cortech Barracuda Box - Inmate Property Storage Box',
 sub='Stack-and-Nest Polypropylene Property Storage Box in Three Sizes for Correctional Facilities',
 cur_sub='Cortech USA 3825P, 7268P, 8568P Barracuda Box - Inmate Property Storage Box',
 intro=['The **Cortech Barracuda Inmate Property Storage Box** gives jails and prisons a tough, lightweight box for inmate property and records. Each box is molded in one piece from high impact “no break” polypropylene, with rounded corners and edges and vertical structural columns that help it stand up to impact.',
  'The stack-and-nest design lets you stack boxes, with or without a lid, without crushing what is inside. Turn an empty box 180 degrees and it nests inside another, which saves storage space and freight. There is a locking hasp on both sides of the box, and the matching Barracuda Box lid is sold separately.'],
 bullets=['**Material:** One-piece injection-molded high impact “no break” '+PP,
  '**Construction:** Rounded corners and edges and vertical structural columns for strength and impact resistance',
  '**Stacking:** Stacks with or without a lid; empty boxes nest when turned 180 degrees',
  '**Locking:** Locking hasp on both sides of the box',
  '**Capacity:** 1.5, 2.0, or 3.0 cu ft',CAL,GRAY,
  '**Lid:** Sold separately as the Cortech Barracuda Box Lid',CLEAN,
  '**Warranty:** 10-year factory warranty',ISO],
 models=['**3825P – Standard, 1.5 cu ft:** 23”W×17½”D×8½”H, fits lid 9689P',
  '**7268P – Large, 2.0 cu ft:** 23”W×17½”D×11½”H, fits lid 9689P',
  '**8568P – Extra Large, 3.0 cu ft:** 28¼”W×18”D×12½”H, fits lid 8289P'],
 install=[NOASM],
 apps=apps('The Barracuda Box is made for allowable in-cell storage and property rooms. With three sizes, facilities can choose the size that fits what each person is allowed to keep.',STO_APPS,STO_COLL),
 series=STO_SERIES,
 mt='Cortech Barracuda Inmate Property Storage Box at Anchortex',
 md='Shop the Cortech Barracuda inmate property storage box. A one-piece polypropylene box in three sizes that stacks or nests, with locking hasps on both sides.',
 notes=['New sections: this is the first Cortech product, so I wrote a new "About Cortech Property Storage" section and a new "About Cortech" paragraph, modeled on the Norix pages. I plan to use the property storage section on the Barracuda Box, Master Box, and both lid pages, and the About Cortech paragraph on every Cortech page, so please review them here.',
  'H1: your current H1 is "Cortech Barracuda Box - Inmate Property Storage Box." I changed it so it reads the same way as the Norix pages and includes the three model numbers. Is that okay?',
  'I left out "the toughest inmate property storage box available" and "stronger, lighter and more functional than other inmate property storage boxes," since these are marketing claims that compare it with other brands.',
  'Numbered boxes: your current page says each Barracuda Box is individually numbered. The Cortech spec sheet and web page say this only for the Master Box, so I left it out.',
  'Dimensions: the Cortech spec sheet lists height × width × depth (for example 8.5” × 23” × 17.5”). I wrote them as width × depth × height, like the other pages. They match your current page.',
  'Shipping weight: Cortech does not publish weights for the Barracuda Box. Your variants are set to 6, 8, and 12 lbs, which look realistic, so I left them as they are.',
  'Product images: the page has one image (an open box). Cortech has photos of the 1.5 cu ft box, the 2.0 cu ft box, and the 3.0 cu ft box with a lid. Would you like me to add them?'])

